attribute vec3 aO, aD; attribute float aT; uniform float uTime; varying float vS, vY, vU;
    vec3 arc(float s){ return mix(aO, aD, s) + vec3(0., 1.70*4.*s*(1. - s) + 1.0, 0.); }
    void main(){
      float u = uTime - aT - 0.45; if (u < 0. || u > 1.55){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float s = position.x*.5 + .5;
      vec3 P = arc(s), T = normalize(arc(min(s + .01, 1.)) - arc(max(s - .01, 0.)));
      vec3 side = normalize(cross(T, P - cameraPosition));
      float W = .5;
      vS = s; vY = position.y*W; vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*W, 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vS, vY, vU; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float s = vS, head = clamp(vU/0.55, 0., 1.);                 // where the Fighter is on the arc
      float wipe = max(vU - 0.75, 0.)/.6;                    // holds after landing, then fades from the take-off point
      float alive = smoothstep(head + .01, head - .1, s)*smoothstep(wipe - .05, wipe + .25, s);
      float prof = sin(3.14159*clamp(s/max(head, .05), 0., 1.));                // thin at take-off and at the body, fullest mid-arc
      float w = (.006 + .052*pow(prof, 1.2));                                       // wide stroke, fullest mid-arc
      float d = abs(vY);
      float band = exp(-pow(d/w, 2.4)), core = lcore(d, w*.3), aura = exp(-pow(d/(w*2.6), 2.))*.08*smoothstep(.5, .32, d);   // soft aura, zero before the strip edge
      float fade = 1. - smoothstep(1.25, 1.55, vU);
      vec3 col = mix(uOrange, uGold, .35 + .65*prof);
      vec3 outc = (col*(band*(.4 + .25*prof) + aura) + mix(uGold, vec3(1., .96, .88), .6)*core*.28*prof)*alive*fade*pow(prof, .7);
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

